package com.securecloud.crypto

import java.security.{KeyPairGenerator, PrivateKey, PublicKey, Signature}
import java.util.concurrent.{ConcurrentHashMap, Executors, ScheduledExecutorService, TimeUnit}
import java.util.concurrent.atomic.AtomicReference
import javax.crypto.{Cipher, KeyGenerator, SecretKey}
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec}
import java.security.SecureRandom

sealed trait KeyState
case object Active extends KeyState
case object Rotating extends KeyState
case object Revoked extends KeyState

class TenantKeyContext(
  val tenantId: String,
  private var _encryptionKey: SecretKey,
  private var _signingKey: PrivateKey,
  val publicKey: PublicKey
) {
  @volatile private var state: KeyState = Active
  private val refCount = new java.util.concurrent.atomic.AtomicInteger(0)

  def acquire(): Boolean = {
    if (state == Revoked) return false
    refCount.incrementAndGet()
    true
  }

  def release(): Unit = {
    val count = refCount.decrementAndGet()
    if (count == 0 && state == Revoked) {
      zeroize()
    }
  }

  def encryptionKey: SecretKey = _encryptionKey
  def signingKey: PrivateKey = _signingKey

  def markRevoked(): Unit = {
    state = Revoked
  }

  def markRotating(): Unit = {
    state = Rotating
  }

  def isActive: Boolean = state == Active
  def currentRefCount: Int = refCount.get()

  private def zeroize(): Unit = {
    _encryptionKey = null
    _signingKey = null
  }
}

class MultiTenantCryptoService(maxTenants: Int = 1000) {
  private val tenantContexts = new ConcurrentHashMap[String, AtomicReference[TenantKeyContext]]()
  private val scheduler: ScheduledExecutorService = Executors.newScheduledThreadPool(2)
  private val random = new SecureRandom()

  def provisionTenant(tenantId: String): Unit = {
    val keyGen = KeyGenerator.getInstance("AES")
    keyGen.init(256, random)
    val encKey = keyGen.generateKey()

    val kpGen = KeyPairGenerator.getInstance("RSA")
    kpGen.initialize(2048, random)
    val keyPair = kpGen.generateKeyPair()

    val ctx = new TenantKeyContext(tenantId, encKey, keyPair.getPrivate, keyPair.getPublic)
    tenantContexts.put(tenantId, new AtomicReference(ctx))
  }

  def encrypt(tenantId: String, plaintext: Array[Byte]): Option[Array[Byte]] = {
    val ref = tenantContexts.get(tenantId)
    if (ref == null) return None

    val ctx = ref.get()
    if (ctx == null || !ctx.acquire()) return None

    try {
      val cipher = Cipher.getInstance("AES/GCM/NoPadding")
      val iv = new Array[Byte](12)
      random.nextBytes(iv)
      val spec = new GCMParameterSpec(128, iv)
      cipher.init(Cipher.ENCRYPT_MODE, ctx.encryptionKey, spec)
      val ciphertext = cipher.doFinal(plaintext)
      Some(iv ++ ciphertext)
    } finally {
      ctx.release()
    }
  }

  def decrypt(tenantId: String, data: Array[Byte]): Option[Array[Byte]] = {
    val ref = tenantContexts.get(tenantId)
    if (ref == null) return None

    val ctx = ref.get()
    if (ctx == null || !ctx.acquire()) return None

    try {
      val iv = data.take(12)
      val ciphertext = data.drop(12)
      val cipher = Cipher.getInstance("AES/GCM/NoPadding")
      val spec = new GCMParameterSpec(128, iv)
      cipher.init(Cipher.DECRYPT_MODE, ctx.encryptionKey, spec)
      Some(cipher.doFinal(ciphertext))
    } finally {
      ctx.release()
    }
  }

  def rotateKey(tenantId: String): Boolean = {
    val ref = tenantContexts.get(tenantId)
    if (ref == null) return false

    val oldCtx = ref.get()
    if (oldCtx == null) return false

    oldCtx.markRotating()

    val keyGen = KeyGenerator.getInstance("AES")
    keyGen.init(256, random)
    val newEncKey = keyGen.generateKey()

    val kpGen = KeyPairGenerator.getInstance("RSA")
    kpGen.initialize(2048, random)
    val newKeyPair = kpGen.generateKeyPair()

    val newCtx = new TenantKeyContext(tenantId, newEncKey, newKeyPair.getPrivate, newKeyPair.getPublic)
    ref.set(newCtx)

    // Schedule cleanup - revoke old context after brief delay
    // BUG: markRevoked() is called immediately, but zeroize happens
    // when refCount hits 0. However, between markRotating() above
    // and markRevoked() below, a concurrent encrypt() call can
    // acquire() the OLD context (since Rotating != Revoked),
    // then after markRevoked + release by another thread drives
    // refCount to 0, zeroize nullifies the key. The thread that
    // acquired during the Rotating window still holds a reference
    // to the now-zeroized context and will use null encryptionKey.
    oldCtx.markRevoked()
    if (oldCtx.currentRefCount == 0) {
      // Force immediate cleanup - this races with acquire()
      oldCtx.release() // drives to -1, but zeroize already happened
    }

    true
  }

  def sign(tenantId: String, data: Array[Byte]): Option[Array[Byte]] = {
    val ref = tenantContexts.get(tenantId)
    if (ref == null) return None

    val ctx = ref.get()
    if (ctx == null || !ctx.acquire()) return None

    try {
      val sig = Signature.getInstance("SHA256withRSA")
      sig.initSign(ctx.signingKey)
      sig.update(data)
      Some(sig.sign())
    } finally {
      ctx.release()
    }
  }

  def verify(tenantId: String, data: Array[Byte], signature: Array[Byte]): Boolean = {
    val ref = tenantContexts.get(tenantId)
    if (ref == null) return false

    val ctx = ref.get()
    if (ctx == null || !ctx.acquire()) return false

    try {
      val sig = Signature.getInstance("SHA256withRSA")
      sig.initVerify(ctx.publicKey)
      sig.update(data)
      sig.verify(signature)
    } finally {
      ctx.release()
    }
  }

  def revokeTenant(tenantId: String): Unit = {
    val ref = tenantContexts.remove(tenantId)
    if (ref != null) {
      val ctx = ref.get()
      if (ctx != null) {
        ctx.markRevoked()
      }
    }
  }

  def shutdown(): Unit = {
    scheduler.shutdown()
    scheduler.awaitTermination(5, TimeUnit.SECONDS)
  }
}
